<template>
  <main class="points-page">
    <nav class="top-nav"><button @click="router.push('/dashboard')">← 工作台</button><div><i>D</i><span><b>Dokiai Academic</b><small>POINTS CENTER</small></span></div><button @click="router.push('/account')">账户中心 →</button></nav>
    <header><span>DOKIAI POINTS CENTER</span><h1>积分中心</h1><p>管理智能服务积分、充值订单与消费记录。</p></header>
    <section class="balance-card"><div><small>CURRENT BALANCE</small><strong>{{ account.points??'--' }}</strong><span>当前可用积分</span></div><div class="balance-meta"><article><span>累计消费</span><b>{{ account.usedPoints??'--' }}</b></article><article><span>累计获得</span><b>{{ account.totalPoints??'--' }}</b></article></div><button class="primary" @click="scrollRecharge">充值积分</button></section>
    <div class="points-grid">
      <section id="recharge" class="panel recharge-panel"><header><div><small>RECHARGE</small><h2>充值积分</h2><p>1 元 = 10 积分，支持 1–100 元自定义金额。</p></div><em>{{ finalAmount*10 }} 积分</em></header><div class="amounts"><button v-for="amount in [10,20,100]" :key="amount" :class="{active:!customSelected&&selectedAmount===amount}" @click="selectAmount(amount)"><b>¥{{ amount }}</b><span>{{ amount*10 }} 积分</span></button><label :class="{active:customSelected}"><span>自定义</span><div><b>¥</b><input v-model.number="customAmount" min="1" max="100" type="number" @focus="customSelected=true"></div><small>1–100 元</small></label></div><footer><div><label><input v-model="payType" type="radio" value="alipay">支付宝</label><label><input v-model="payType" type="radio" value="wechat">微信支付</label></div><button class="primary" :disabled="creating" @click="createOrder">{{ creating?'正在创建…':`立即充值 ¥${finalAmount}` }}</button></footer></section>
      <aside class="panel guide"><small>POINTS GUIDE</small><h2>积分如何使用</h2><ul><li><i>✦</i><span><b>智能文档创作</b><small>根据实际生成规则扣除积分</small></span></li><li><i>Aa</i><span><b>学术优化</b><small>按服务规则计算消耗</small></span></li><li><i>✓</i><span><b>到账记录</b><small>支付成功后自动更新余额</small></span></li></ul></aside>
    </div>
    <div class="history-grid">
      <section class="panel"><header><small>USAGE HISTORY</small><h2>消费记录</h2></header><div v-if="consumption.length" class="list"><article v-for="(item,index) in consumption" :key="item.id||index"><span><b>{{ item.featureName||item.description||item.remark||'智能服务' }}</b><small>{{ formatTime(item.createdAt||item.created_at) }}</small></span><strong>−{{ Math.abs(Number(item.points||item.amount||0)) }}</strong></article></div><div v-else class="empty">暂无消费记录</div></section>
      <section class="panel"><header><small>RECHARGE ORDERS</small><h2>充值订单</h2></header><div v-if="orders.length" class="list"><article v-for="order in orders.slice(0,8)" :key="order.orderNo"><span><b>{{ order.orderNo }}</b><small>{{ formatTime(order.createdAt||order.created_at) }} · {{ statusText(order.status) }}</small></span><strong>¥{{ order.amount }} / {{ order.points }}积分</strong></article></div><div v-else class="empty">暂无充值订单</div></section>
    </div>
  </main>
</template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { useRouter } from 'vue-router';import { createRechargeOrder,getPointAccount,getPointTransactions,getRechargeOrders,getRechargePlans } from '../../api/rewrite'
const router=useRouter(),account=ref({}),transactions=ref([]),orders=ref([]),plans=ref([]),selectedAmount=ref(10),customAmount=ref(1),customSelected=ref(false),payType=ref('alipay'),creating=ref(false)
const finalAmount=computed(()=>customSelected.value?Math.max(1,Math.min(100,Number(customAmount.value)||1)):selectedAmount.value),consumption=computed(()=>transactions.value.filter(item=>Number(item.points??item.amount)<0).slice(0,8))
function selectAmount(v){selectedAmount.value=v;customSelected.value=false}function scrollRecharge(){document.getElementById('recharge')?.scrollIntoView({behavior:'smooth'})}function formatTime(v){return v?String(v).replace('T',' ').slice(0,16):'--'}function statusText(v){return({pending:'待支付',paid:'支付成功',failed:'支付失败',refunded:'已退款'})[v]||v||'--'}
async function load(){try{const [a,t,o,p]=await Promise.all([getPointAccount(),getPointTransactions().catch(()=>[]),getRechargeOrders(),getRechargePlans()]);account.value=a||{};transactions.value=t?.list||t||[];orders.value=o||[];plans.value=p||[]}catch(e){ElMessage.warning(e?.responseData?.message||e.message||'积分数据暂时无法读取')}}
async function createOrder(){const amount=finalAmount.value;if(amount<1||amount>100)return ElMessage.warning('充值金额必须为 1–100 元');creating.value=true;try{const plan=plans.value.find(x=>Number(x.amount)===amount),order=await createRechargeOrder({planId:plan?.planId||null,amount,payMethod:payType.value});if(!order?.paymentUrl)return ElMessage.error('支付链接生成失败，请稍后重试');window.location.href=order.paymentUrl}finally{creating.value=false}}
onMounted(load)
</script>
