ay:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:18px 0}.amounts button,.amounts label{display:grid;gap:5px;padding:16px;border:1px solid #e7e3ef;border-radius:13px;background:#fff}.amounts button b{font-size:22px}.amounts span,.amounts small{color:#9198a7;font-size:9px}.amounts .active{border-color:#8f7aea;background:#f7f3ff;box-shadow:0 0 0 2px #e8e0ff}.amounts label div{display:flex;gap:5px}.amounts input{width:70px;border:0;outline:0;font-size:19px}.recharge-panel footer{display:flex;justify-content:space-between;align-items:center;padding-top:14px;border-top:1px solid #efecf5}.recharge-panel footer>div{display:flex;gap:14px}.guide ul{display:grid;gap:14px;margin:18px 0 0;padding:0;list-style:none}.guide li{display:flex;gap:10px}.guide li i{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#eee9ff;color:#6e4fff;font-style:normal}.guide li span{display:grid}.guide li small{color:#9298a7;letter-spacing:0}.history-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.list{margin-top:14px}.list article{display:flex;align-items:center;justify-content:space-between;padding:11px;border-bottom:1px solid #f0edf5}.list span{display:grid}.list small{color:#969cab;letter-spacing:0}.list strong{color:#6e4fff}.empty{display:grid;place-items:center;min-height:130px;color:#989ead}@media(max-width:900px){.balance-card,.points-grid,.history-grid{grid-template-columns:1fr}.amounts{grid-template-columns:1fr 1fr}}@media(max-width:600px){.points-page{padding-inline:12px}.balance-meta,.recharge-panel footer{align-items:stretch;flex-direction:column}.amounts{grid-template-columns:1fr}}
